package com.gen3.recommenderagent.inputparser;

import com.gen3.recommenderagent.domain.Intent;
import com.gen3.recommenderagent.domain.session.Constraints;
import com.gen3.recommenderagent.domain.session.Preferences;
import com.gen3.recommenderagent.domain.session.Query;

/** The small response shape generated by the AI input parser. */
public class ParsedRequest {

  private boolean personalised;
  private Intent intent;
  private Query query;
  private Preferences preferences;
  private Constraints constraints;

  public ParsedRequest() {}

  public boolean isPersonalised() {
    return personalised;
  }

  public void setPersonalised(boolean personalised) {
    this.personalised = personalised;
  }

  public Intent getIntent() {
    return intent;
  }

  public void setIntent(Intent intent) {
    this.intent = intent;
  }

  public Query getQuery() {
    return query;
  }

  public void setQuery(Query query) {
    this.query = query;
  }

  /** Returns preference terms extracted by the AI parser. */
  public Preferences getPreferences() {
    return preferences;
  }

  /** Stores preference terms so they can be copied into the session request. */
  public void setPreferences(Preferences preferences) {
    this.preferences = preferences;
  }

  /** Returns exact language, duration, and count constraints from the parser. */
  public Constraints getConstraints() {
    return constraints;
  }

  /** Stores parsed constraints so retrieval can build Qdrant payload filters. */
  public void setConstraints(Constraints constraints) {
    this.constraints = constraints;
  }
}
